pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp and block.difficulty to force random=1 for first player, random=0 for second
        // First call: random=1 (lose)
        vm.warp(1);
        vm.roll(1);
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.play{value: 10}();

        // Second call: random=0 (win) - after adjusting timestamp/difficulty
        // Using a different block to change random outcome
